class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        n = len(nums)
        ok = [[nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0 for j in range(n)] for i in range(n)]
        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 1
        for mask in range(1 << n):
            row = dp[mask]
            for last in range(n):
                v = row[last]
                if not v:
                    continue
                for nxt in range(n):
                    if not (mask >> nxt) & 1 and ok[last][nxt]:
                        nm = mask | 1 << nxt
                        dp[nm][nxt] = (dp[nm][nxt] + v) % MOD
        return sum(dp[(1 << n) - 1]) % MOD

