class Solution {
public:
    int specialPerm(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        vector<vector<bool>> ok(n, vector<bool>(n));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                ok[i][j] = nums[i] % nums[j] == 0 || nums[j] % nums[i] == 0;
        vector<vector<long long>> dp(1 << n, vector<long long>(n, 0));
        for (int i = 0; i < n; i++) dp[1 << i][i] = 1;
        for (int mask = 0; mask < (1 << n); mask++)
            for (int last = 0; last < n; last++) {
                long long v = dp[mask][last];
                if (!v) continue;
                for (int nxt = 0; nxt < n; nxt++)
                    if (!(mask >> nxt & 1) && ok[last][nxt])
                        dp[mask | 1 << nxt][nxt] = (dp[mask | 1 << nxt][nxt] + v) % MOD;
            }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans = (ans + dp[(1 << n) - 1][i]) % MOD;
        return ans;
    }
};

