var specialPerm = function(nums) {
    const MOD = 1e9 + 7, n = nums.length;
    const ok = Array.from({length: n}, (_, i) =>
        Array.from({length: n}, (_, j) => nums[i] % nums[j] === 0 || nums[j] % nums[i] === 0));
    const dp = Array.from({length: 1 << n}, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) dp[1 << i][i] = 1;
    for (let mask = 0; mask < 1 << n; mask++)
        for (let last = 0; last < n; last++) {
            const v = dp[mask][last];
            if (!v) continue;
            for (let nxt = 0; nxt < n; nxt++)
                if (!(mask >> nxt & 1) && ok[last][nxt])
                    dp[mask | 1 << nxt][nxt] = (dp[mask | 1 << nxt][nxt] + v) % MOD;
        }
    return dp[(1 << n) - 1].reduce((a, b) => (a + b) % MOD, 0);
