class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        from functools import lru_cache
        MOD = 10 ** 9 + 7
        n = len(nums)
        full = (1 << n) - 1
        @lru_cache(None)
        def dfs(mask, last):
            if mask == full:
                return 1
            r = 0
            for nxt in range(n):
                if not (mask >> nxt) & 1 and (nums[last] % nums[nxt] == 0 or nums[nxt] % nums[last] == 0):
                    r = (r + dfs(mask | 1 << nxt, nxt)) % MOD
            return r
        return sum(dfs(1 << i, i) for i in range(n)) % MOD

