    static constexpr long long MODV = 1e9 + 7;
    int specialPerm(vector<int>& nums) {
        a = nums; n = nums.size(); full = (1 << n) - 1;
        memo.assign(1 << n, vector<long long>(n, -1));
        long long ans = 0;
        for (int i = 0; i < n; i++) ans = (ans + dfs(1 << i, i)) % MODV;
